/// <summary>
/// One serial number that left the warehouse - picked, shipped or sold - with what took it out.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSerialHistoryRow
{
    str        itemId;
    str        itemName;
    str        serialId;
    str        batchId;
    str        reference;
    str        referenceType;
    str        status;
    str        transDate;
    real       quantity;
}

Method.Source:
